#!/usr/bin/env node
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const EXAMPLE = path.join(ROOT, "examples", "grout-vault-all-in-one.html");
const html = fs.readFileSync(EXAMPLE, "utf8");

for (const marker of [
    "Generated by scripts/generate-grout-vault.mjs",
    "architecture:\"grout-vault-all-in-one\"",
    'meta name="apple-mobile-web-app-capable" content="yes"',
    'meta name="mobile-web-app-capable" content="yes"',
    'meta name="apple-mobile-web-app-status-bar-style" content="black-translucent"',
    "host:\"fullscreen\"",
    "GENERATED_DATA_BEGIN",
    "GENERATED_DATA_END",
    "GM.grout13.addPayload",
    "GM.grout13.addFontPayload",
    "GM.camera.createRoomView",
    "GM.layer.compose",
    "GM.input.createVirtualJoystick",
    "layer:\"controls\"",
    "pointerKinds",
    "pulseButtonRect",
    "pausePointerId",
    "resumePointerId",
    "drones:",
    "triggerPulse",
    "keyPressed(GM.key.SPACE)",
    "health:",
    "collection:",
    "outcome:",
    "triggerWin",
    "triggerLoss",
    "TAP TO RESTART"
]) {
    assert.ok(html.includes(marker), `Grout Vault all-in-one is missing marker: ${marker}`);
}
assert.equal(/fruit-shot\/(?:font|atlas)-payload|\bfrom\s+["']\.\//i.test(html), false, "Grout Vault must embed game-owned payloads without local module imports");
assert.equal(/compileGrout13Atlas|native-app-shell|data-gm-app-shell|viewport-fit=|theme-color/i.test(html), false, "Grout Vault must be payload-first and DOM-shell independent");
assert.equal(/if\s*\(\s*pointer\.released\s*\)\s*\{\s*state\.paused\s*=\s*false/.test(html), false, "Grout Vault must not resume from the activating pause release");
assert.equal(/\bTODO\b|\bFIXME\b/.test(html), false, "Grout Vault must not ship unfinished markers");

const executable = html
    .match(/<script\b([^>]*)>([\s\S]*?)<\/script\s*>/gi)
    ?.find((value) => !/type\s*=\s*["']importmap["']/i.test(value))
    ?.replace(/^<script\b[^>]*>|<\/script\s*>$/gi, "")
    .replace(/^import[^\n]*\n/gm, "") || "";
assert.ok(executable.includes("GM.app.start"), "Grout Vault must have an executable game script");
try {
    new Function(executable);
} catch (error) {
    assert.fail(`Grout Vault executable script has a syntax error: ${error instanceof Error ? error.message : String(error)}`);
}

console.log("[ok] Grout Vault all-in-one source contract passed with embedded payloads and complete game-state paths.");
